function buildRocket(){let p=progress[2];return `<g transform="translate(440 192)"><path d="M-42 78h84v133h-84Z" fill="#fff4d6" stroke="#a49e81" stroke-width="3"/><path d="M-42 191h84v22h-84Z" fill="#d87a50"/>${p.has('nose')?'<path d="M-42 78Q-37 25 0 0q37 25 42 78Z" fill="#db794c"/>':'<path d="M-42 78Q-37 25 0 0q37 25 42 78Z" fill="none" stroke="#78927c" stroke-width="3" stroke-dasharray="7 7"/>'}${p.has('window')?'<circle cy="117" r="25" fill="#dbaa64"/><circle cy="117" r="18" fill="#8dbdc7"/><path d="m-9 113 15-11" stroke="#d4edf0" stroke-width="5"/>':'<circle cy="117" r="25" fill="none" stroke="#78927c" stroke-width="3" stroke-dasharray="7 7"/>'}${p.has('fins')?'<path d="M-43 139-73 172v57l35-28m81-62 30 33v57l-35-28" fill="#648871"/>':'<path d="M-43 139-73 172v57l35-28m81-62 30 33v57l-35-28" fill="none" stroke="#78927c" stroke-width="3" stroke-dasharray="7 7"/>'}<path d="M-29 214h58v12h-58Z" fill="#718168"/></g>`;}
function tapButton(key,label,x,y,content,classes=''){const done=progress[pageIndex].has(key);return `<button class="scene-tap ${classes} ${done?'tapped':''}" data-tap="${key}" style="left:${x}%;top:${y}%" aria-label="${label}" ${done?'disabled':''}><span class="tap-object">${content}</span>${done?'':'<span class="tap-cue">'+hand+'</span>'}</button>`;}
function activities(){let p=progress[pageIndex],type=pages[pageIndex].type;
 if(type==='dream')return `<div class="rocket-drawing"><span class="draw-title">Johnny’s rocket idea</span><canvas id="rocket-drawing-canvas" width="480" height="230" aria-label="Draw your rocket idea here"></canvas><div class="draw-actions"><button id="clear-drawing" type="button">Clear</button><button id="save-drawing" type="button" disabled>Save my rocket</button></div></div>`;
 if(type==='supplies')return `<div class="supply-drag-zone" data-drop-target="supplies" aria-label="Johnny’s supply basket">${p.size>=3?'Basket full!':'Drop supplies here'}</div><div class="supply-drag-tray">`+[['box','BOX','▰'],['colander','HAT','◉'],['tape','TAPE','◎']].map(([k,label,c])=>`<button class="drag-token supply-token ${p.has(k)?'tapped':''}" data-drag="${k}" aria-label="Drag ${label.toLowerCase()} to the basket" ${p.has(k)?'disabled':''}><span>${p.has(k)?'✓':c}</span><small>${label}</small></button>`).join('')+'</div>';
 if(type==='build')return `<div class="rocket-drop-zones">${[['nose','Top'],['window','Window'],['fins','Fins']].map(([k,l])=>`<div class="rocket-drop-zone ${p.has(k)?'placed':''}" data-drop-target="${k}" aria-label="${l} rocket part slot">${p.has(k)?'✓':''}</div>`).join('')}</div><div class="piece-tray building">`+[['nose','TOP','▲'],['window','WINDOW','◉'],['fins','FINS','◀ ▶']].map(([k,label,c])=>`<button class="drag-token piece-button ${p.has(k)?'tapped':''}" data-drag="${k}" aria-label="Drag rocket ${label.toLowerCase()} into place" ${p.has(k)?'disabled':''}><span class="build-piece">${p.has(k)?'✓':c}<small>${label}</small></span></button>`).join('')+'</div>';
 if(type==='route')return `<div class="journey-target moon-target ${p.has('route')?'placed':''}" data-drop-target="route" aria-label="Moon orbit target"><span>MOON</span></div><button class="drag-token journey-token route-token ${p.has('route')?'tapped':''}" data-drag="route" aria-label="Drag Johnny’s rocket toward the Moon" ${p.has('route')?'disabled':''} style="left:14%;top:72%">🚀</button>`;
 if(type==='solar')return `<div class="celestial-discoveries">${tapButton('spot-mars','Tap the red planet',83,30,'<span class="discover-ping">✦</span>','discovery-tap')}${tapButton('spot-rings','Tap the ringed planet',54,53,'<span class="discover-ping">✦</span>','discovery-tap')}${tapButton('spot-comet','Tap the comet',81,12,'<span class="discover-ping">✦</span>','discovery-tap')}</div>`;
 if(type==='meteors')return `<div class="meteor-hotspots">${['meteor-1','meteor-2','meteor-3'].map((key,i)=>{const spots=[[28,25],[57,28],[80,40]];return `<button class="meteor-clear-button" data-clear-meteor="${key}" style="left:${spots[i][0]}%;top:${spots[i][1]}%" aria-label="Tap space rock ${i+1} to send it fizzing away"><span class="meteor-symbol">☄</span><span class="meteor-tap-hint">${hand}</span></button>`;}).join('')}</div>`;
 if(type==='moon')return `<div class="journey-target moon-orbit-target ${p.has('moonOrbit')?'placed':''}" data-drop-target="moonOrbit" aria-label="Moon orbit target"><span>ORBIT</span></div><button class="drag-token journey-token moon-token ${p.has('moonOrbit')?'tapped':''}" data-drag="moonOrbit" aria-label="Drag the rocket around the Moon" ${p.has('moonOrbit')?'disabled':''} style="left:13%;top:67%">🚀</button>`;
 if(type==='approach')return tapButton('landing','Tap the bright spot to help Johnny land',78,68,'LAND HERE','landing-tap');
 if(type==='launch')return `<div class="launch-handle ${p.has('launch')?'pulled':''}" role="button" tabindex="0" aria-disabled="${p.has('launch')}" aria-label="Pull the launch handle down"><span>☟</span><small>PULL</small></div>`;
 if(type==='land')return `<div class="lunch-swipe-target" aria-label="Swipe the lunchbox lid open"><span class="lunch-lid">${p.has('lunch')?'OPEN!':'SWIPE'}</span></div>`;
 return '';
}

function markActivityDone(key){if(progress[pageIndex].has(key))return;progress[pageIndex].add(key);renderReader();if(progress[pageIndex].size>=pages[pageIndex].goal)celebrate();}
function setupHandsOnActivities(){
 const canvas=$('#rocket-drawing-canvas');
 if(canvas){const ctx=canvas.getContext('2d');let drawing=false,ink=0,last=null;ctx.lineWidth=8;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#d97548';if(savedSketch){const saved=new Image();saved.onload=()=>ctx.drawImage(saved,0,0,canvas.width,canvas.height);saved.src=savedSketch;ink=25;$('#clear-drawing').disabled=true;}const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;canvas.setPointerCapture(e.pointerId);last=point(e);ctx.beginPath();ctx.moveTo(last.x,last.y);ink++;});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const q=point(e);ctx.lineTo(q.x,q.y);ctx.stroke();ink+=Math.hypot(q.x-last.x,q.y-last.y);last=q;$('#save-drawing').disabled=ink<24;});canvas.addEventListener('pointerup',()=>{drawing=false;last=null;});canvas.addEventListener('pointercancel',()=>{drawing=false;last=null;});$('#clear-drawing').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ink=0;$('#save-drawing').disabled=true;};$('#save-drawing').onclick=()=>{if(ink<24)return;savedSketch=canvas.toDataURL();progress[pageIndex].add('sketch');$('#save-drawing').disabled=true;$('#clear-drawing').disabled=true;$('#story-art').classList.add('complete');const card=$('.activity-card');card.classList.add('activity-done');$('.activity-label').textContent='YOU DID IT!';$('#activity-message').textContent=pages[pageIndex].success;$('.activity-icon').innerHTML=spark;$('.activity-dots').innerHTML='<i class="filled"></i>';syncPageGate();celebrate();};}
 document.querySelectorAll('[data-clear-meteor]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.clearMeteor;if(progress[pageIndex].has(key))return;progress[pageIndex].add(key);button.disabled=true;button.classList.add('meteor-clearing');const rock=$(`#meteor-art-${key.slice(-1)}`);rock?.classList.add('meteor-zapped');updateActivityProgress();if(progress[pageIndex].size>=pages[pageIndex].goal)celebrate();}));
 document.querySelectorAll('[data-drag]').forEach(token=>{let startX=0,startY=0;token.addEventListener('pointerdown',e=>{if(token.disabled)return;e.preventDefault();token.setPointerCapture(e.pointerId);startX=e.clientX;startY=e.clientY;token.classList.add('dragging');});token.addEventListener('pointermove',e=>{if(!token.classList.contains('dragging'))return;token.style.setProperty('--dx',(e.clientX-startX)+'px');token.style.setProperty('--dy',(e.clientY-startY)+'px');});token.addEventListener('pointerup',e=>{if(!token.classList.contains('dragging'))return;token.classList.remove('dragging');const x=e.clientX,y=e.clientY;token.style.removeProperty('--dx');token.style.removeProperty('--dy');const target=[...document.querySelectorAll('[data-drop-target]')].find(z=>{const r=z.getBoundingClientRect();return x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom;});const targetKey=target?.dataset.dropTarget,key=token.dataset.drag;const valid=target&&(targetKey==='supplies'&&['box','colander','tape'].includes(key)||targetKey===key);if(valid)markActivityDone(key);else{token.classList.add('drop-back');setTimeout(()=>token.classList.remove('drop-back'),280);}});token.addEventListener('pointercancel',()=>{token.classList.remove('dragging');token.style.removeProperty('--dx');token.style.removeProperty('--dy');});});
 const handle=$('.launch-handle');if(handle){let start=0;handle.addEventListener('pointerdown',e=>{if(progress[pageIndex].has('launch'))return;start=e.clientY;handle.setPointerCapture(e.pointerId);handle.classList.add('pulling');});handle.addEventListener('pointermove',e=>{if(handle.classList.contains('pulling'))handle.style.setProperty('--pull',Math.max(0,Math.min(90,e.clientY-start))+'px');});const finish=e=>{if(!handle.classList.contains('pulling'))return;const pulled=e.clientY-start;handle.classList.remove('pulling');handle.style.removeProperty('--pull');if(pulled>55)play('launch');};handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',()=>handle.classList.remove('pulling'));handle.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!progress[pageIndex].has('launch')){e.preventDefault();play('launch');}});}
 const lid=$('.lunch-lid');if(lid){let start=0;lid.addEventListener('pointerdown',e=>{if(progress[pageIndex].has('lunch'))return;start=e.clientX;lid.setPointerCapture(e.pointerId);lid.classList.add('sliding');});lid.addEventListener('pointermove',e=>{if(lid.classList.contains('sliding'))lid.style.setProperty('--slide',Math.max(0,Math.min(130,e.clientX-start))+'px');});const finish=e=>{if(!lid.classList.contains('sliding'))return;const dx=e.clientX-start;lid.classList.remove('sliding');lid.style.removeProperty('--slide');if(dx>55)play('lunch');};lid.addEventListener('pointerup',finish);lid.addEventListener('pointercancel',()=>lid.classList.remove('sliding'));lid.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!progress[pageIndex].has('lunch')){e.preventDefault();play('lunch');}});}
}

function lineWords(pageIndex,lineIndex){return pages[pageIndex].lines[lineIndex].match(/\S+/g)||[];}
function pageIsComplete(index){return reading[index].done&&progress[index].size>=pages[index].goal;}
function renderStoryText(){const p=pages[pageIndex],state=reading[pageIndex],words=lineWords(pageIndex,state.line);if(state.done)return `<div class="reading-lines">${p.lines.map(t=>`<p class="read-line read-line-done">${t}</p>`).join('')}</div><div class="reading-coach"><span class="reading-count">All lines read!</span><button class="read-next-line" disabled>All done! ✓</button></div>`;const completed=state.line===0?'':p.lines.slice(0,state.line).map(t=>`<p class="read-line read-line-done">${t}</p>`).join('');const current=`<p class="read-line read-line-current">${words.map((w,i)=>`<span class="story-word ${i<state.word?'word-shown':''} ${i===state.word-1?'word-current':''} ${i>=state.word?'word-pending':''}" data-word="${i}">${w}</span>`).join(' ')}</p>`;const ready=state.word>=words.length;return `<div class="reading-lines" aria-label="Story text, one word at a time">${completed}${current}</div><div class="reading-coach"><span class="reading-count">Part ${state.line+1} of ${p.lines.length}</span><button id="read-next-line" class="read-next-line" ${ready&&state.line<p.lines.length-1?'':'disabled'}>${ready?(state.line<p.lines.length-1?'Read the next part →':'All done! ✓'):'Follow each word…'}</button></div>`;}
function scheduleNextWord(){clearTimeout(wordTimer);wordTimer=null;const state=reading[pageIndex];if(state.done)return;const words=lineWords(pageIndex,state.line);if(state.word>=words.length)return;wordTimer=setTimeout(()=>{const artWord=$(`#reader .read-line-current [data-word="${state.word}"]`);if(artWord){artWord.classList.remove('word-pending');artWord.classList.add('word-shown','word-current');const prev=$(`#reader .read-line-current [data-word="${state.word-1}"]`);prev?.classList.remove('word-current');}state.word++;if(state.word>=words.length){$(`#reader .read-line-current [data-word="${state.word-1}"]`)?.classList.remove('word-current');if(state.line===pages[pageIndex].lines.length-1)state.done=true;const coach=$('#reader .reading-coach');if(coach){coach.innerHTML=`<span class="reading-count">Part ${state.line+1} of ${pages[pageIndex].lines.length}</span><button id="read-next-line" class="read-next-line" ${state.line<pages[pageIndex].lines.length-1?'':'disabled'}>${state.line<pages[pageIndex].lines.length-1?'Read the next part →':'All done! ✓'}</button>`;$('#read-next-line')?.addEventListener('click',advanceLine);}syncPageGate();}else scheduleNextWord();},wordDelay);}
function syncPageGate(){const canContinue=pageIsComplete(pageIndex),next=$('#next');if(next){next.disabled=!canContinue;next.textContent=pageIndex===pages.length-1?'Finish story ✓':canContinue?'Next page →':reading[pageIndex].done?'Finish the page activity to continue':'Read each part to continue';}document.querySelectorAll('[data-page]').forEach(b=>{b.disabled=Number(b.dataset.page)>pageIndex+1||Number(b.dataset.page)>pageIndex&&!canContinue;});const tip=$('.reader-tip');if(tip)tip.textContent=canContinue?'Great reading! Turn the page for the next surprise.':reading[pageIndex].done?'Great reading! Finish the little activity to turn the page.':'Read each little part and finish the page activity to turn the page.';}
function advanceLine(){const state=reading[pageIndex],words=lineWords(pageIndex,state.line);if(state.word<words.length)return;if(state.line<pages[pageIndex].lines.length-1){state.line++;state.word=0;renderReader();}}
function renderReader(){clearTimeout(wordTimer);wordTimer=null;const p=pages[pageIndex],complete=progress[pageIndex].size>=p.goal,ready=pageIsComplete(pageIndex);$('#reader').innerHTML=`<div class="reader-top"><button class="back-shelf" id="back-shelf">← <span>Bookshelf</span></button><span class="reader-book-title">Johnny Builds to Mars</span><button id="sound-toggle" class="sound-toggle" aria-pressed="${speechEnabled}" aria-label="${speechEnabled?'Stop reading aloud':'Read this page aloud'}">${speechEnabled?'◼':'▷'} <span>${speechEnabled?'Stop reading':'Read to me'}</span></button></div><section class="story-spread" aria-labelledby="story-title"><div class="story-art ${p.type} ${complete?'complete':''}" id="story-art"><svg viewBox="0 0 700 530" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${sceneBase(p.type,complete)}</svg>${activities()}<span class="scene-caption">${p.type==='dream'?'Draw Johnny’s rocket idea in the sky.':p.type==='supplies'?'Drag the supplies into Johnny’s basket.':p.type==='build'?'Drag rocket parts into place. Pickles is watching!':p.type==='launch'?'Pull the handle. Ready… set… WHOOSH!':p.type==='route'?'Drag the rocket along its moonlit path.':p.type==='solar'?'Tap the planets and comet to spot Johnny’s space neighbors.':p.type==='meteors'?'Tap the space rocks to make them fizz away!':p.type==='moon'?'Steer around the Moon. Keep on going!':p.type==='approach'?'Tap the glowing spot to help Johnny land.':'Swipe the lunchbox lid open!'}</span><div class="countdown" id="countdown" aria-live="assertive"></div></div><div class="story-copy"><p class="eyebrow">CHAPTER ${String(pageIndex+1).padStart(2,'0')} <span>✦</span> ${pageIndex===pages.length-1?'A RED PLANET. AN EMPTY TUMMY.':'A LITTLE BIG ADVENTURE'}</p><h1 id="story-title">${p.name}</h1><div id="story-text">${renderStoryText()}</div><div class="activity-card ${complete?'activity-done':''}"><span class="activity-icon">${complete?spark:hand}</span><div><span class="activity-label">${complete?'YOU DID IT!':'YOUR TURN, LITTLE EXPLORER'}</span><p id="activity-message" role="status">${complete?p.success:progress[pageIndex].size?`${progress[pageIndex].size} of ${p.goal} done! Find the next one.`:p.instruction}</p><div class="activity-dots" aria-label="${progress[pageIndex].size} of ${p.goal} completed">${Array.from({length:p.goal},(_,i)=>`<i class="${i<progress[pageIndex].size?'filled':''}"></i>`).join('')}</div>${ready&&!complete?'<span class="gate-note">One more little task to turn the page.</span>':''}</div></div>${pageIndex===pages.length-1?'<button id="read-again" class="read-again">Read again <span>↻</span></button>':''}</div></section><div class="reader-navigation"><button id="previous" class="page-button" ${pageIndex===0?'disabled':''}>← <span>Back</span></button><div class="page-indicator"><div class="page-dots">${pages.map((p,i)=>`<button data-page="${i}" class="${i===pageIndex?'current':''} ${pageIsComplete(i)?'visited':''}" aria-label="Page ${i+1}: ${p.name}" ${i>pageIndex+1||i>pageIndex&&!ready?'disabled':''} ${i===pageIndex?'aria-current="page"':''}></button>`).join('')}</div><span>Page ${pageIndex+1} of ${pages.length}</span></div><button id="next" class="page-button next" ${!ready||!complete?'disabled':''}>${pageIndex===pages.length-1?'Finish story ✓':ready?'Next page →':'Read the words to continue'}</button></div><p class="reader-tip">${hand} Read each little part and finish the page activity to turn the page.</p>`;
 $('#back-shelf').onclick=returnShelf;$('#previous').onclick=()=>goPage(pageIndex-1);$('#next').onclick=()=>pageIndex===pages.length-1?returnShelf():goPage(pageIndex+1);$('#sound-toggle').onclick=toggleSpeech;
 if(!('speechSynthesis' in window))$('#sound-toggle').hidden=true;
 document.querySelectorAll('[data-tap]').forEach(b=>b.onclick=()=>play(b.dataset.tap));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>goPage(Number(b.dataset.page)));
 setupHandsOnActivities();
 $('#read-next-line')?.addEventListener('click',advanceLine);
 if($('#read-again'))$('#read-again').onclick=()=>{progress=pages.map(()=>new Set());savedSketch=null;reading=pages.map(()=>({line:0,word:0,done:false}));goPage(0);};
 scheduleNextWord();
}
function goPage(i){if(turningPage||i===pageIndex||i<0||i>=pages.length||i>pageIndex+1||i>pageIndex&&!pageIsComplete(pageIndex))return;clearTimeout(wordTimer);wordTimer=null;clearTimeout(pageTimer);launching=false;window.speechSynthesis?.cancel();const direction=i>pageIndex?'forward':'back';const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(reducedMotion){pageIndex=i;renderReader();window.scrollTo({top:0,behavior:'instant'});if(speechEnabled)speakPage();return;}turningPage=true;$('#reader').classList.add('page-turning');$('#reader .story-spread')?.classList.add(`page-exit-${direction}`);pageTransitionTimer=setTimeout(()=>{pageIndex=i;renderReader();window.scrollTo({top:0,behavior:'instant'});const spread=$('#reader .story-spread');spread?.classList.add(`page-enter-${direction}`);pageTransitionTimer=setTimeout(()=>{spread?.classList.remove(`page-enter-${direction}`);$('#reader').classList.remove('page-turning');turningPage=false;pageTransitionTimer=null;},520);if(speechEnabled)speakPage();},260);}

function play(key){if(progress[pageIndex].has(key)||launching)return;
 if(pages[pageIndex].type==='launch'){launching=true;$('#story-art').classList.add('rumbling');$('.launch-handle')?.setAttribute('aria-disabled','true');let n=3;const count=()=>{if(n>0){$('#countdown').textContent=n--;pageTimer=setTimeout(count,850);}else{progress[pageIndex].add('launch');launching=false;renderReader();$('#story-art').classList.add('blast-off');}};count();return;}
 progress[pageIndex].add(key);const button=$(`[data-tap="${key}"]`);if(button){button.disabled=true;button.classList.add('tapped');}if(pages[pageIndex].type==='approach'&&key==='landing')$('#story-art').classList.add('landing-guided');updateActivityProgress();
 const scene=$('#story-art');if(scene){for(let i=0;i<6;i++){const bit=document.createElement('span');bit.className='tap-spark';bit.textContent=i%2?'✦':'•';bit.style.setProperty('--spark-x',(Math.random()*130-65)+'px');bit.style.setProperty('--spark-y',(Math.random()*100-50)+'px');bit.style.left=(50+Math.random()*18-9)+'%';bit.style.top=(42+Math.random()*16-8)+'%';scene.appendChild(bit);bit.addEventListener('animationend',()=>bit.remove());}}
 if(progress[pageIndex].size>=pages[pageIndex].goal)celebrate();
}
function updateActivityProgress(){const p=pages[pageIndex],done=progress[pageIndex].size,complete=done>=p.goal,card=$('.activity-card');if(!card)return;card.classList.toggle('activity-done',complete);$('.activity-label').textContent=complete?'YOU DID IT!':'YOUR TURN, LITTLE EXPLORER';$('#activity-message').textContent=complete?p.success:pages[pageIndex].type==='solar'?`${done} of ${p.goal} space neighbors spotted! Keep looking.`:`${done} of ${p.goal} done! Keep looking.`;$('.activity-icon').innerHTML=complete?spark:hand;document.querySelectorAll('.activity-dots i').forEach((dot,i)=>dot.classList.toggle('filled',i<done));$('#story-art').classList.toggle('complete',complete);const gate=card.querySelector('.gate-note');if(complete)gate?.remove();else if(reading[pageIndex].done&&!gate)card.lastElementChild.insertAdjacentHTML('beforeend','<span class="gate-note">One more little task to turn the page.</span>');syncPageGate();}
function celebrate(){const a=$('#story-art');for(let i=0;i<14;i++){let s=document.createElement('span');s.className='confetti';s.textContent=i%2?'✦':'●';s.style.setProperty('--dx',(Math.random()*380-190)+'px');s.style.setProperty('--r',(Math.random()*180-90)+'deg');s.style.left=(35+Math.random()*30)+'%';s.style.color=['#edbf5c','#e88961','#f7efcb'][i%3];a.appendChild(s);s.addEventListener('animationend',()=>s.remove());}}
function speakPage(){if(!window.speechSynthesis)return;window.speechSynthesis.cancel();const p=pages[pageIndex],s=new SpeechSynthesisUtterance(p.name+'. '+p.lines.join(' ')+' '+p.instruction);s.lang='en-US';s.rate=.85;s.pitch=1.1;s.onend=()=>{speechEnabled=false;if($('#sound-toggle')){$('#sound-toggle').setAttribute('aria-pressed','false');$('#sound-toggle').innerHTML='▷ <span>Read to me</span>';}};window.speechSynthesis.speak(s);}
function toggleSpeech(){speechEnabled=!speechEnabled;if(speechEnabled)speakPage();else window.speechSynthesis?.cancel();const b=$('#sound-toggle');b.setAttribute('aria-pressed',String(speechEnabled));b.setAttribute('aria-label',speechEnabled?'Stop reading aloud':'Read this page aloud');b.innerHTML=(speechEnabled?'◼':'▷')+' <span>'+(speechEnabled?'Stop reading':'Read to me')+'</span>';}
window.addEventListener('hashchange',()=>{if(location.hash!=='#book'&&!$('#reader').hidden)returnShelf();else if(location.hash==='#book'&&$('#reader').hidden)openBook();});
window.addEventListener('keydown',e=>{if($('#reader').hidden||!e.target.closest||e.target.closest('button,a'))return;if(e.key==='ArrowRight')goPage(pageIndex+1);if(e.key==='ArrowLeft')goPage(pageIndex-1);if(e.key==='Escape')returnShelf();});
if(location.hash==='#book')openBook();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_johnny_book_page',description:'Open a page of Johnny Builds to Mars. Later pages unlock after a child reads the current page and completes its activity.',inputSchema:{type:'object',properties:{page:{type:'integer',minimum:1,maximum:pages.length}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({page})=>{if(!Number.isInteger(page)||page<1||page>pages.length)throw new Error(`Choose a page from 1 to ${pages.length}.`);if($('#reader').hidden)openBook();if(page-1>pageIndex&&!pageIsComplete(pageIndex))throw new Error('Finish reading and playing on this page to continue.');goPage(page-1);return {page:pageIndex+1,title:pages[pageIndex].name,activity:pages[pageIndex].instruction};}});}catch(e){console.info('Book tools are unavailable.');}}
